window.QB_POOLS=window.QB_POOLS||{};window.QB_POOLS["q762876c5ed"]={"type":"常识时政","questions":[{"qid":"sy-a-20250329-001","no":1,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20250329-001-题目-p01-116-308.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"③④"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20250329-001-解析-p01-42-188.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"中国共产党第二十届中央纪律检查委员会第四次全体会议，于2025 年1 月6 日至8 日在北京举行。全会提出，要持续深化整治群众身边不正之风和腐败问题，着力推动改革发展成果更好更公平惠及广大人民群众。下列哪项属于该内容中的突出问题？（）\n\n①跨境腐败\n\n②金融领域监管\n\n③医保基金管理\n\n④乡村振兴资金使用监管","options":[{"k":"A","t":"①②"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"③④"}],"material":"","explanation":"1\n\n本题考查时政真题。\n\n中国共产党第二十届中央纪律检查委员会第四次全体会议指出：持续深化整治群众身边不正之风和腐败问题，着力推动改革发展成果更好更公平惠及广大人民群众。持续发力惩治“蝇贪蚁腐”，聚焦县以下这一关键环节、薄弱环节持续抓下去。深化“校园餐”、农村集体“三资”管理、乡村振兴资金使用监管、医保基金管理、养老服务等方面突出问题治理，扎实推进整治殡葬领域腐败乱象专项行动。指导各地选择民生痛点难点因地制宜开展整治，让群众可感可及。\n\n综上所述：③④正确。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/A类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"pcc5bbcd4be","sourceYears":[2025]},{"qid":"sy-a-20250329-002","no":2,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20250329-002-题目-p01-304-417.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"明确提出来到2025 年末要取得的多项阶段性成效"},{"k":"B","t":"建成教育强国是高质量教育体系初步形成的重要体现"},{"k":"C","t":"人民群众教育获得感提升先于人民群众教育满意度跃升"},{"k":"D","t":"学习型社会全面形成与人才自主培养质量全面提高同步实现"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20250329-002-解析-p01-183-498.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"中共中央国务院印发了《教育强国建设规划纲要（2024 2035）》，关于其中的主要目标，下列说法正确的是（）。","options":[{"k":"A","t":"明确提出来到2025 年末要取得的多项阶段性成效"},{"k":"B","t":"建成教育强国是高质量教育体系初步形成的重要体现"},{"k":"C","t":"人民群众教育获得感提升先于人民群众教育满意度跃升"},{"k":"D","t":"学习型社会全面形成与人才自主培养质量全面提高同步实现"}],"material":"","explanation":"2\n\n本题考查时政真题。\n\n《教育强国建设规划纲要（20242035）》（以下简称《纲要》）提出：“到2027年，教育强国建设取得重要阶段性成效。各级教育普及水平持续巩固提升，高质量教育体系初步形成，人民群众教育获得感明显提升，人才自主培养质量全面提高，拔尖创新人才不断涌现，关键领域改革取得实质性进展，教育布局结构与经济社会和人口高质量发展需求更加契合，具有全球影响力的重要教育中心建设迈上新台阶。到2035年，建成教育强国。党对教育事业全面领导的制度体系和工作机制系统完备，高质量教育体系全面建成，基础教育普及水平和质量稳居世界前列，学习型社会全面形成，人民群众教育满意度显著跃升，教育服务国家战略能力显著跃升，教育现代化总体实现。”\n\nA项错误，《纲要》明确提出到2027年，教育强国建设取得重要阶段性成效，而并非2025年。\n\nB项错误，《纲要》明确提出，到2027年，教育强国建设取得重要阶段性成效，其中包括高质量教育体系初步形成。到2035年，目标是建成教育强国，此时高质量教育体系全面建成。这说明高质量教育体系的初步形成是教育强国建设的一人阶段目标，而并非建成教育强国是高质量教育体系初步形成的重要体现。\n\nC项正确，《纲要》明确提出，到2027年，人民群众教育获得感明显提升，到2035年，人民群众教育满意度显著跃升。因此，人民群众教育获得感明显提升是2027年的目标，人民群众教育满意度显著跃升是2035年的目标，人民群众教育获得感提升先于人民群众教育满意度跃升。\n\nD项错误，《纲要》明确提出，到2027年，人才自主培养质量全面提高，到2035年，学习型社会全面形成。因此，人才自主培养质量全面提高是2027年底的目标，学习型社会全面形成是2035年目标，人才自主培养质量全面提高先于学习型社会全面形成。\n\n故正确答案为 C。"},"from":{"file":"07-事业编职测/A类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"pcc5bbcd4be","sourceYears":[2025]},{"qid":"sy-a-20250329-003","no":3,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20250329-003-题目-p01-413-526.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"省级养老机构负责兜底保障"},{"k":"B","t":"乡镇敬老院不允许委托运营"},{"k":"C","t":"街道应当建设综合养老服务平台"},{"k":"D","t":"社区可发展互助性养老服务站点"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20250329-003-解析-p01-494-753.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20250329-003-解析-p02-47-108.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"深化养老服务改革发展是实施积极应对人口老龄化国家战略的迫切要求。根据《中共中央国务院关于深化养老服务改革发展的意见》，下列关于覆盖城乡的三级养老服务网络的说法，正确的是（）。","options":[{"k":"A","t":"省级养老机构负责兜底保障"},{"k":"B","t":"乡镇敬老院不允许委托运营"},{"k":"C","t":"街道应当建设综合养老服务平台"},{"k":"D","t":"社区可发展互助性养老服务站点"}],"material":"","explanation":"3\n\n本题考查时政真题。\n\nA项错误，《中共中央国务院关于深化养老服务改革发展的意见》指出：（一）建设县级综合养老服务管理平台。依托县级特困人员供养服务机构和养老服务信息系统，建设综合养老服务管理平台，在承担兜底保障职能基础上，拓展和强化服务示范、行业指导、应急救助、资源协调等综合功能。故应该是县级养锁车老机构负责兜底保障，不是省级养老机构。\n\nB项错误，《中共中央国务院关于深化养老服务改革发展的意见》指出：支持有条件的地方推动乡镇（街道）敬老院由县级民政部门直管，探索推广委托运营，提升服务管理质效。故选项“乡镇敬老院不允许委托运营”说法错误。\n\nC项错误，《中共中央国务院关于深化养老服务改革发展的意见》指出：建设县级综合养老服务管理平台；加强乡镇（街道）区域养老服务能力建设；完善村（社区）养老服务设施站点。所以应该是县级建设综合养老服务平台，不是街道。\n\nD项正确，《中共中央国务院关于深化养老服务改革发展的意见》指出：完善村（社区）养老服务设施站点。发挥乡镇（街道）区域养老服务中心带动作用，采取“中心十站点”等方式，大力发展嵌入式社区养老服务设施、互助性养老服务站点，完善老旧小区养老服务设施，加强与教育、卫生健康、文化等公共服务设施的综合利用，建设“一老一小”服务综合体。发挥设施站点连接家庭与社会服务的作用，及时收集和转介服务需求。所以社区可发展互助性养老服务站点。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/A类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[1,2]},"idx":2,"pid":"pcc5bbcd4be","sourceYears":[2025]},{"qid":"sy-a-20250329-004","no":4,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20250329-004-题目-p01-522-714.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①——维护乡村和谐稳定"},{"k":"B","t":"②——加快农业绿色低碳发展"},{"k":"C","t":"③——推进基础设施提档升级"},{"k":"D","t":"④——加快涉农法律法规制定修订"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20250329-004-解析-p02-104-342.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2025 年1 月，中共中央、国务院印发了《乡村全面振兴规划（2024-2027 年)》。以下是该文件的部分主要内容：\n\n①深化农业农村改革，激发农村发展活力\n\n②繁荣乡村文化，培育新时代文明乡风\n\n③建设宜居宜业和美乡村，增进农民福祉\n\n④加强农村基层组织建设，推进乡村治理现代化下列关于文件中的主要内容与其具体做法，匹配正确的是（）。","options":[{"k":"A","t":"①——维护乡村和谐稳定"},{"k":"B","t":"②——加快农业绿色低碳发展"},{"k":"C","t":"③——推进基础设施提档升级"},{"k":"D","t":"④——加快涉农法律法规制定修订"}],"material":"","explanation":"4\n\n本题考查时政真题。\n\nA项错误，根据《乡村全面振兴规划（2024-2027年）》：深化农业农村改革，激发农村发展活力的内容包括：巩固和完善农村基本经营制度；深化农村土地制度改革；健全多元化乡村振兴投入保障机制；扎实推进农村改革各项重点任务。选项中“维护乡村和谐稳定”不属于其内容。\n\nB项错误，根据《乡村全面振兴规划（2024-2027年）》：繁荣乡村文化，培育新时代文明乡风的内容包括：提升乡村精神风貌；重塑乡村文化生态；增强乡村文化影响力。选项中“加快农业绿色低碳发展”不属于其内容。\n\nC项正确，根据《乡村全面振兴规划（2024-2027年）》：建设宜居宜业和美乡村，增进农民福的内容包括：推进基础设施提档升级；持续改善人居环境；稳步提升基本公共服务水平；完善农村社区服务设施；加快数字乡村建设；优化乡村规划建设。选项中“推进基础设施提档升级”属于其内容。\n\nD项错误，根据《乡村全面振兴规划（2024-2027年）》：加强农村基层组织建设，推进乡村治理现代化的内容包括：深入推进抓党建促乡村全面振兴；推进以党建引领乡村治理；维护乡村和谐稳定。选项中“加快涉农法律法规制定修订”不属于其内容。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/A类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[2]},"idx":3,"pid":"pcc5bbcd4be","sourceYears":[2025]},{"qid":"sy-a-20250329-005","no":5,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1,2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20250329-005-题目-p01-709-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20250329-005-题目-p02-51-136.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"构建国家、省、城市三级平台体系"},{"k":"B","t":"重新打造超大规模城市的智能中枢"},{"k":"C","t":"加强多个部门城市运行数据的共享"},{"k":"D","t":"推进城市运行管理服务“一网统管”"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20250329-005-解析-p02-338-562.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"《中共中央办公厅国务院办公厅关于推进新型城市基础设施建设打造韧性城市的意见》提出“搭建完善城市运行管理服务平台”。对此，下列说法错误的是（）。","options":[{"k":"A","t":"构建国家、省、城市三级平台体系"},{"k":"B","t":"重新打造超大规模城市的智能中枢"},{"k":"C","t":"加强多个部门城市运行数据的共享"},{"k":"D","t":"推进城市运行管理服务“一网统管”"}],"material":"","explanation":"5\n\n本题考查时政真题。\n\n2024年11月26日，《中共中央办公厅国务院办公厅关于推进新型城市基础设施建设打造韧性城市的意见》（以下简称《意见》）发布。\n\nA项正确，B项错误，《意见》指出，加快构建国家、省、城市三级平台体系，加强与城市智能中枢等现有平台系统的有效衔接，实现信息共享、分级监管、协同联动。并非“重新打造超大规模城市的智能中枢”。\n\nC项正确，《意见》指出，完善城市运行管理工作机制，加强城市运行管理服务平台与应急管理、工业和信息化、公安、自然资源、生态环境、交通运输、水利、商务、卫生健康、市场监管、气象、数据管理、消防救援、地震等部门城市运行数据的共享，增强城市运行安全风险监测预警能力。故“加强多个部门城市运行数据的共享”说法正确。\n\nD项正确，《意见》指出，加强对城市运行管理服务状况的实时监测、动态分析、统筹协调、指挥监督和综合评价，推进城市运行管理服务“一网统管”。\n\n本题为选非题，故正确答案为B。"},"from":{"file":"07-事业编职测/A类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1,2],"answerPages":[2]},"idx":4,"pid":"pcc5bbcd4be","sourceYears":[2025]},{"qid":"sy-a-20250329-006","no":6,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[2,3]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20250329-006-题目-p02-132-324.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20250329-006-解析-p02-557-753.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20250329-006-解析-p03-47-93.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2024 年9 月，习近平总书记在甘肃省兰州市主持召开全面推动黄河流域生态保护和高质量发展座谈会，会上习近平总书记指出，要实施最严格的水资源保护利用制度，提高水资源节约集约利用水平。下列属于该内容的是（）。\n\n①实施节水行动，加快建设节水型社会\n\n②积极探索和规范推进水权交易，全面推行水资源费改税\n\n③提升县城产业和人口承载能力，减轻生态脆弱区的承载压力\n\n④健全覆盖全流域的取用水总量控制体系，科学配置干支流水资源","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"6\n\n本题考查时政真题。\n\n屏锁车2024年9月，习近平总书记在甘肃省兰州市主持召开全面推动黄河流域生态保护和高质量发展座谈会。\n\n会上习近平指出，要实施最严格的水资源保护利用制度，提高水资源节约集约利用水平。严守水资源开发利用上限，细化以水定城、以水定地、以水定人、以水定产举措，健全覆盖全流域的取用水总量控制体系，科学配置干支流水资源。强化地下水水位管控，加大中下游地下水超采漏斗治理力度。加强饮用水水源地保护。稳步优化调整“八七”分水方案。积极探索和规范推进水权交易，全面推行水资源费改税。实施节水行动，加快建设节水型社会。\n\n习近平指出，要统筹新型城镇化和乡村振兴，稳步增进民生福。引导大中小城市和小城镇协调发展、集约紧凑布局，提升县城产业和人口承载能力，减轻生态脆弱区的承载压力。\n\n综上所述：①②④都属于“要实施最严格的水资源保护利用制度，提高水资源节约集约利用水平”的内容，③属于“要统筹新型城镇化和乡村振兴，稳步增进民生福补”的内容。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/A类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[2,3]},"idx":5,"pid":"pcc5bbcd4be","sourceYears":[2025]},{"qid":"sy-b-20250329-001","no":1,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20250329-001-题目-p01-116-308.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"③④"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20250329-001-解析-p01-38-184.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"中国共产党第二十届中央纪律检查委员会第四次全体会议，于2025 年1 月6 日至8 日在北京举行。全会提出，要持续深化整治群众身边不正之风和腐败问题，着力推动改革发展成果更好更公平惠及广大人民群众。下列哪项属于该内容中的突出问题？（）\n\n①跨境腐败\n\n②金融领域监管\n\n③医保基金管理\n\n④乡村振兴资金使用监管","options":[{"k":"A","t":"①②"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"③④"}],"material":"","explanation":"1\n\n本题考查时政真题。\n\n中国共产党第二十届中央纪律检查委员会第四次全体会议指出：持续深化整治群众身边不正之风和腐败问题，着力推动改革发展成果更好更公平惠及广大人民群众。持续发力惩治“蝇贪蚁腐”，聚焦县以下这一关键环节、薄弱环节持续抓下去。深化“校园餐”、农村集体“三资”管理、乡村振兴资金使用监管、医保基金管理、养老服务等方面突出问题治理，扎实推进整治殡葬领域腐败乱象专项行动。指导各地选择民生痛点难点因地制宜开展整治，让群众可感可及。\n\n综上所述：③④正确。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/B类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"p57dadcab56","sourceYears":[2025]},{"qid":"sy-b-20250329-002","no":2,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20250329-002-题目-p01-304-495.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①——维护乡村和谐稳定"},{"k":"B","t":"②——加快农业绿色低碳发展"},{"k":"C","t":"③——推进基础设施提档升级"},{"k":"D","t":"④——加快涉农法律法规制定修订"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20250329-002-解析-p01-180-418.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2025 年1 月，中共中央、国务院印发了《乡村全面振兴规划（2024-2027 年)》。以下是该文件的部分主要内容：\n\n①深化农业农村改革，激发农村发展活力\n\n②繁荣乡村文化，培育新时代文明乡风\n\n③建设宜居宜业和美乡村，增进农民福祉\n\n④加强农村基层组织建设，推进乡村治理现代化下列关于文件中的主要内容与其具体做法，匹配正确的是（）。","options":[{"k":"A","t":"①——维护乡村和谐稳定"},{"k":"B","t":"②——加快农业绿色低碳发展"},{"k":"C","t":"③——推进基础设施提档升级"},{"k":"D","t":"④——加快涉农法律法规制定修订"}],"material":"","explanation":"2\n\n本题考查时政真题。\n\nA项错误，根据《乡村全面振兴规划（2024-2027年）》：深化农业农村改革，激发农村发展活力的内容包括：巩固和完善农村基本经营制度；深化农村土地制度改革；健全多元化乡村振兴投入保障机制；扎实推进农村改革各项重点任务。选项中“维护乡村和谐稳定”不属于其内容。\n\nB项错误，根据《乡村全面振兴规划（2024-2027年)》：繁荣乡村文化，培育新时代文明乡风的内容包括：提升乡村精神风貌；重塑乡村文化生态；增强乡村文化影响力。选项中“加快农业绿色低碳发展”不属于其内容。\n\nC项正确，根据《乡村全面振兴规划（2024-2027年）》：建设宜居宜业和美乡村，增进农民福证的内容包括：推进基础设施提档升级；持续改善人居环境；稳步提升基本公共服务水平；完善农村社区服务设施；加快数字乡村建设；优化乡村规划建设。选项中“推进基础设施提档升级”属于其内容。\n\nD项错误，根据《乡村全面振兴规划（2024-2027年)》：加强农村基层组织建设，推进乡村治理现代化的内容包括：深入推进抓党建促乡村全面振兴；推进以党建引领乡村治理；维护乡村和谐稳定。选项中“加快涉农法律法规制定修订”不属于其内容。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/B类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[1]},"idx":1,"pid":"p57dadcab56","sourceYears":[2025]},{"qid":"sy-b-20250329-004","no":4,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1,2],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20250329-004-题目-p01-600-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-b-20250329-004-题目-p02-51-105.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20250329-004-解析-p01-522-744.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-b-20250329-004-解析-p02-46-74.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2024 年9 月，习近平总书记在甘肃省兰州市主持召开全面推动黄河流域生态保护和高质量发展座谈会，会上习近平总书记指出，要实施最严格的水资源保护利用制度，提高水资源节约集约利用水平。下列属于该内容的是（）。\n\n①实施节水行动，加快建设节水型社会\n\n②积极探索和规范推进水权交易，全面推行水资源费改税\n\n③提升县城产业和人口承载能力，减轻生态脆弱区的承载压力\n\n④健全覆盖全流域的取用水总量控制体系，科学配置干支流水资源","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"4\n\n本题考查时政真题。\n\n2024年9月，习近平总书记在甘肃省兰州市主持召开全面推动黄河流域生态保护和高质量发展座谈会。\n\n会上习近平指出，要实施最严格的水资源保护利用制度，提高水资源节约集约利用水平。严守水资源开发利用上限，细化以水定城、以水定地、以水定人、以水定产举措，健全覆盖全流域的取用水总量控制体系，科学配置干支流水资源。强化地下水水位管控，加大中下游地下水超采漏斗治理力度。加强饮用水水源地保护。稳步优化调整“八七”分水方案。积极探索和规范推进水权交易，全面推行水资源费改税。实施节水行动，加快建设节水型社会。\n\n习近平指出，要统筹新型城镇化和乡村振兴，稳步增进民生福。引导大中小城市和小城镇协调发展、集约紧凑布局，提升县城产业和人口承载能力，减轻生态脆弱区的承载压力。\n\n综上所述：①②④都属于“要实施最严格的水资源保护利用制度，提高水资源节约集约利用水平”的内容，③属于“要统筹新型城镇化和乡村振兴，稳步增进民生福”的内容。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/B类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1,2],"answerPages":[1,2]},"idx":3,"pid":"p57dadcab56","sourceYears":[2025]},{"qid":"sy-c-20250329-001","no":1,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20250329-001-题目-p01-116-230.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"健全收粮农民收益保障机制，落实最高收购价政策"},{"k":"B","t":"完善粮食主产区利益补偿机制，强化对粮食主产区的支持"},{"k":"C","t":"统筹建立粮食产销区省级纵向利益补偿机制，建立健全稳定的帮扶关系"},{"k":"D","t":"落实粮食作物部分成本和种植收入保险政策，鼓励各省份实施均等化保费补贴政策"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20250329-001-解析-p01-42-279.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2025 年1 月，中共中央、国务院印发的《乡村全面振兴规划（2024-2027 年)》提出，要加快现代农业建设，全方位夯实粮食安全根基。下列关于该文件中加大粮食生产支持力度的说法，正确的是（）。","options":[{"k":"A","t":"健全收粮农民收益保障机制，落实最高收购价政策"},{"k":"B","t":"完善粮食主产区利益补偿机制，强化对粮食主产区的支持"},{"k":"C","t":"统筹建立粮食产销区省级纵向利益补偿机制，建立健全稳定的帮扶关系"},{"k":"D","t":"落实粮食作物部分成本和种植收入保险政策，鼓励各省份实施均等化保费补贴政策"}],"material":"","explanation":"1\n\n本题考查时政真题。\n\n《乡村全面振兴规划（2024-2027年）》提出：（八）加大粮食生产支持力度。健全种粮农民收益保障机制，完善粮食生产补贴，落实最低收购价政策，健全农资保供稳价应对机制，落实粮食作物完全成本和种植收入保险政策，鼓励有条件的省份实施差异化保费补贴政策，加大对产粮大县的支持力度。完善粮食主产区利益补偿机制，强化对粮食主产区的支持，合理安排产粮大县奖励资金规模，实施产粮大县公共服务能力提升行动，统筹建立粮食产销区省际横向利益补偿机制，建立健全稳定的协作关系。\n\nA项错误，根据原文应该是：健全种粮农民收益保障机制，落实最低收购价政策，选项中“最高收购价格政策”表述错误。\n\nB项正确，完善粮食主产区利益补偿机制，强化对粮食主产区的支持，符合原文表述。\n\nC项错误，根据原文应该是：统筹建立粮食产销区省际横向利益补偿机制，建立健全稳定的协作关系，选项中“纵向利益补充机制”和“帮扶关系”表述错误。\n\nD项错误，根据原文应该是：落实粮食作物完全成本和种植收入保险政策，鼓励有条件的省份实施差异化保费补贴政策，选项中“粮食农作物部分成本”、“各省份”和“均等化保费补贴政策”表述错误。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"p7ad5ce2a45","sourceYears":[2025]},{"qid":"sy-c-20250329-003","no":3,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20250329-003-题目-p01-335-448.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"以调结构、促改革为基本前提"},{"k":"B","t":"以保持制造业比重基本稳定为主要途径"},{"k":"C","t":"以服务实体经济和人民群众为出发点、落脚点"},{"k":"D","t":"社会物流总费用与国内生产总值的比率力争升至20%"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20250329-003-解析-p01-384-622.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2024 年11 月，中共中央办公厅、国务院办公厅印发了《有效降低全社会物流成本行动方案》，关于该方案，下列说法正确的是（）。","options":[{"k":"A","t":"以调结构、促改革为基本前提"},{"k":"B","t":"以保持制造业比重基本稳定为主要途径"},{"k":"C","t":"以服务实体经济和人民群众为出发点、落脚点"},{"k":"D","t":"社会物流总费用与国内生产总值的比率力争升至20%"}],"material":"","explanation":"3\n\n本题考查时政真题。\n\n《有效降低全社会物流成本行动方案》指出：坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三中全会精神，完整准确全面贯彻新发展理念，以服务实体经济和人民群众为出发点、落脚点，以保持制造业比重基本稳定为基本前提，以调结构、促改革为主要途径，处理好调整结构与深化改革、建强网络与畅通末梢、打造枢纽与优化布局的关系，促进全社会物流资源配置效率最优化和效益最大化，提高物流组织化程度和效率，促进物流与产业融合创新，加强协同衔接和要素保障解决物流发展不平衡不充分问题，统筹推动物流成本实质性下降，有效降低运输成本、仓储成本、管理成本，为增强产业核心竞争力、畅通国民经济循环提供有力支撑。\n\nA项错误，根据原文应该是：以调结构、促改革为主要途径，选项中“基本前提”，表述错误。\n\nB项错误，根据原文应该是：以保持制造业比重基本稳定为基本前提，选项中“主要途径”，表述错误。\n\nC项正确，以服务实体经济和人民群众为出发点、落脚点，符合原文。。伯\n\nD项错误，《有效降低全社会物流成本行动方案》指出：主要目标是：到2027年，社会物流总费用与国内生产总值的比率力争降至13.5%左右。选项中“升至20%”，表述错误。\n\n故正确答案为 C。"},"from":{"file":"07-事业编职测/C类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[1]},"idx":2,"pid":"p7ad5ce2a45","sourceYears":[2025]},{"qid":"sy-c-20250329-004","no":4,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20250329-004-题目-p01-444-558.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"省级养老机构负责兜底保障"},{"k":"B","t":"乡镇敬老院不允许委托运营"},{"k":"C","t":"街道应当建设综合养老服务平台"},{"k":"D","t":"社区可发展互助性养老服务站点"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20250329-004-解析-p01-618-735.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20250329-004-解析-p02-46-232.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"深化养老服务改革发展是实施积极应对人口老龄化国家战略的迫切要求。根据《中共中央国务院关于深化养老服务改革发展的意见》，下列关于覆盖城乡的三级养老服务网络的说法，正确的是（）。","options":[{"k":"A","t":"省级养老机构负责兜底保障"},{"k":"B","t":"乡镇敬老院不允许委托运营"},{"k":"C","t":"街道应当建设综合养老服务平台"},{"k":"D","t":"社区可发展互助性养老服务站点"}],"material":"","explanation":"4\n\n本题考查时政真题。\n\nA项错误，《中共中央国务院关于深化养老服务改革发展的意见》指出：（一）建设县级综合养老服务管理平台。依托县级特困人员供养服务机构和养老服务信息系统，建设综合养老服务管理平台，在承担兜底保障职能基础上，拓展和强化服务示范、行业指导、应急救助、资源协调等综合功能。故应该是县级养老机构负责兜底保障，不是省级养老机构。\n\nB项错误，《中共中央国务院关于深化养老服务改革发展的意见》指出：支持有条件的地方推动乡镇（街道）敬老院由县级民政部门直管，探索推广委托运营，提升服务管理质效。故选项“乡镇敬老院不允许委托运营”说法错误。\n\nC项错误，《中共中央国务院关于深化养老服务改革发展的意见》指出：建设县级综合养老服务管理平台；加强乡镇（街道）区域养老服务能力建设；完善村（社区）养老服务设施站点。所以应该是县级建设综合养老服务平台，不是街道。\n\nD项正确，《中共中央国务院关于深化养老服务改革发展的意见》指出：完善村（社区）养老服务设施站点。发挥乡镇（街道）区域养老服务中心带动作用，采取“中心十站点”等方式，大力发展嵌入式社区养老服务设施、互助性养老服务站点，完善老旧小区养老服务设施，加强与教育、卫生健康、文化等公共服务设施的综合利用，建设“一老一小”服务综合体。发挥设施站点连接家庭与社会服务的作用，及时收集和转介服务需求。所以社区可发展互助性养老服务站点。\n\n故正确答案为 D。"},"from":{"file":"07-事业编职测/C类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[1,2]},"idx":3,"pid":"p7ad5ce2a45","sourceYears":[2025]},{"qid":"sy-c-20250329-005","no":5,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20250329-005-题目-p01-553-667.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"构建国家、省、城市三级平台体系"},{"k":"B","t":"重新打造超大规模城市的智能中枢"},{"k":"C","t":"加强多个部门城市运行数据的共享"},{"k":"D","t":"推进城市运行管理服务“一网统管”"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20250329-005-解析-p02-228-450.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"《中共中央办公厅国务院办公厅关于推进新型城市基础设施建设打造韧性城市的意见》提出“搭建完善城市运行管理服务平台”。对此，下列说法错误的是（）。","options":[{"k":"A","t":"构建国家、省、城市三级平台体系"},{"k":"B","t":"重新打造超大规模城市的智能中枢"},{"k":"C","t":"加强多个部门城市运行数据的共享"},{"k":"D","t":"推进城市运行管理服务“一网统管”"}],"material":"","explanation":"5\n\n本题考查时政真题。\n\n2024年11月26日，《中共中央办公厅国务院办公厅关于推进新型城市基础设施建设打造韧性城市的意见》（以下简称《意见》）发布。\n\nA项正确，B项错误，《意见》指出，加快构建国家、省、城市三级平台体系，加强与城市智能中枢等现有平台系统的有效衔接，实现信息共享、分级监管、协同联动。并非“重新打造超大规模城市的智能中枢”。\n\nC项正确，《意见》指出，完善城市运行管理工作机制，加强城市运行管理服务平台与应急管理、工业和信息化、公安、自然资源、生态环境、交通运输、水利、商务、卫生健康、市场监管、气象、数据管理、消防救援、地震等部门城市运行数据的共享，增强城市运行安全风险监测预警能力。故“加强多个部门城市运行数据的共享”说法正确。\n\nD项正确，《意见》指出，加强对城市运行管理服务状况的实时监测、动态分析、统筹协调、指挥监督和综合评价，推进城市运行管理服务“一网统管”。\n\n本题为选非题，故正确答案为B。"},"from":{"file":"07-事业编职测/C类/2025/2025-03-29/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[2]},"idx":4,"pid":"p7ad5ce2a45","sourceYears":[2025]},{"qid":"sy-b-20251025-001","no":1,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20251025-001-题目-p02-106-213.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"“狼牙山五壮士”：该英雄事迹发生在井冈山革命根据地"},{"k":"B","t":"“平型关大战突击连”：平型关大捷发生在百团大战之后"},{"k":"C","t":"“杨靖宇支队”：杨靖宇是东北抗日联军主要创建者和领导人"},{"k":"D","t":"“琼崖纵队英勇善战连”：琼崖纵队为广西抗战作出突出贡献"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20251025-001-解析-p01-144-684.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"纪念中国人民抗日战争暨世界反法西斯战争胜利80周年阅兵活动中，80面抗战英模部队荣誉旗帜组成的战旗方队接受祖国和人民检阅。下列和战旗称号有关的说法，正确的是（    ）。","options":[{"k":"A","t":"“狼牙山五壮士”：该英雄事迹发生在井冈山革命根据地"},{"k":"B","t":"“平型关大战突击连”：平型关大捷发生在百团大战之后"},{"k":"C","t":"“杨靖宇支队”：杨靖宇是东北抗日联军主要创建者和领导人"},{"k":"D","t":"“琼崖纵队英勇善战连”：琼崖纵队为广西抗战作出突出贡献"}],"material":"","explanation":"1\n\n本题考查时事政治。\n\nA 项错误，狼牙山五壮士是抗日战争时期在河北易县狼牙山面对日本侵略军浴血奋战、宁死不屈、英勇跳崖的5 名八路军战士：马宝玉、胡德林、胡福才、葛振林和宋学义。他们的壮举表现了崇高的爱国主义、革命英雄主义精神和坚贞不屈的民族气节，他们用生命和鲜血谱写出气吞山河的革命壮歌。河北省易县在抗日战争时期属于晋察冀抗日根据地，并非井冈山革命根据地。\n\nB 项错误，1937 年9 月25 日，陆军第79 集团军某合成旅“平型关大战突击连”前身八路军第115 师343 旅685 团2 营5 连，作为突击队，冒雨在关沟以北高地伏击日军，在敌我双方力量极其悬殊的情况下，全连官兵奋勇冲入敌阵，与敌展开白刃战。平型关大捷是全民族抗战爆发后，中国军队主动对日作战取得的第一个重大胜利，打破了日军“不可战胜”的神话。\n\n战后，连队被授予“平型关大战突击连”荣誉称号。1940 年8 月，为粉碎侵华日军的“囚笼政策”，中国共产党领导的八路军在华北发动了百团大战。这是抗日战争中八路军在华北地区发动的规模最大、持续时间最长的一次带战略性进攻的战役。因此，平型关大捷发生在百团大战之前。\n\nC 项正确，杨靖宇，原名马尚德，1905 年出生于河南省确山县一个农民家庭，是抗日民族英雄、东北抗日联军的主要创建者和领导人之一，在东北地区坚持抗日斗争。\n\nD 项错误，琼崖纵队第1 总队7 团1 连，前身为琼山县讨逆革命军一部。1939 年至1945年，1 连随部队孤岛奋战，积极克服武器装备落后等方面劣势，采用夜袭战、麻雀战、伏击战等灵活机动的战术打击日伪军，多次取得战斗胜利，为海南抗战作出突出贡献。琼崖纵队授予该连“英勇善战连”荣誉称号。选项中“为广西抗战作出突出贡献”的表述有误。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/B类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1]},"idx":0,"pid":"p071b6c2956","sourceYears":[2025]},{"qid":"sy-b-20251025-002","no":2,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20251025-002-题目-p02-208-315.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"地方和部门文件要阐述形势背景、重大意义，并提出报送贯彻落实情况的要求"},{"k":"B","t":"已制发文件的工作事项应当召开直达基层的电视电话或网络视频会议专门部署"},{"k":"C","t":"上级部门到地方督查检查可通过签订承诺书、第三方评估的方式设置考核事项"},{"k":"D","t":"中央和国家机关部门原则上最多运行1个面向基层的政务移动互联网应用程序"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20251025-002-解析-p01-679-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-b-20251025-002-解析-p02-51-400.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"形式主义、官僚主义是顽瘴痼疾，必须坚决纠治。2025年8月，中共中央办公厅、国务院办公厅印发了《整治形式主义为基层减负若干规定》，根据该规定的内容，下列说法正确的是（    ）。","options":[{"k":"A","t":"地方和部门文件要阐述形势背景、重大意义，并提出报送贯彻落实情况的要求"},{"k":"B","t":"已制发文件的工作事项应当召开直达基层的电视电话或网络视频会议专门部署"},{"k":"C","t":"上级部门到地方督查检查可通过签订承诺书、第三方评估的方式设置考核事项"},{"k":"D","t":"中央和国家机关部门原则上最多运行1个面向基层的政务移动互联网应用程序"}],"material":"","explanation":"2\n\n本题考查时事政治。\n\nA 项错误，《整治形式主义为基层减负若干规定》指出，文件应当开门见山、直奔主题，着重提出贯彻落实的政策措施，一般不必阐述形势背景、重要意义、主要原则等内容，确需阐述的应当简明扼要。\n\nB 项错误，《整治形式主义为基层减负若干规定》指出，已制发文件的工作事项原则上不再专门开会部署。未经同级党委主要负责同志批准，不得随意召开直达基层的会议（含电视电话、网络视频会议），对已直接开到基层的，不再层层召开。\n\nC 项错误，《整治形式主义为基层减负若干规定》指出，不得随意设置“一票否决”和签订责任状事项，不得通过签订承诺书、第三方评估、满意度测评、挂牌督办等方式变相设置考核事项。\n\nD 项正确，《整治形式主义为基层减负若干规定》指出，清理整合面向基层的政务应用程序。\n\n中央和国家机关部门原则上最多运行1 个面向基层的政务移动互联网应用程序，填表报数交材料功能一般不向下延伸到县级；现有多个政务应用程序到基层的，应当逐步清理压减整合。\n\n故正确答案为D"},"from":{"file":"07-事业编职测/B类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1,2]},"idx":1,"pid":"p071b6c2956","sourceYears":[2025]},{"qid":"sy-b-20251025-003","no":3,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[2,3]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20251025-003-题目-p02-311-434.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20251025-003-解析-p02-395-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-b-20251025-003-解析-p03-51-136.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"习近平总书记指出，推进中国式现代化必须推动海洋经济高质量发展，走出一条具有中国特色的向海图强之路。关于海洋强国建设，下列说法正确的是（    ）。\n\n①建设海洋强国是实现中华民族伟大复兴的重大战略任务\n\n②要加强海湾经济发展规划研究，有序推进沿海港口群优化整合\n\n③要保护海洋生态环境，着力推动海洋开发方式向经济利益主导型转变\n\n④建设强大的现代化海军是建设世界一流军队的重要标志，是建设海洋强国的战略支撑","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"3\n\n本题考查时事政治。\n\n①项正确，2022 年4 月10 日，习近平总书记在中国海洋大学三亚海洋研究院调研考察时，对建设海洋强国作出重要指示：“建设海洋强国是实现中华民族伟大复兴的重大战略任务。”\n\n②项正确，2025 年7 月1 日，习近平主持召开中央财经委员会第六次会议强调：“推动海洋经济高质量发展，要加强顶层设计，加大政策支持力度······要加强海湾经济发展规划研究，有序推进沿海港口群优化整合。”\n\n③项错误，习近平总书记在主持中共中央政治局就建设海洋强国研究进行集体学习时（2013年7 月30 日）强调了建设海洋强国的四个基本要求，即“四个转变”。具体内容为：要提高海洋资源开发能力，着力推动海洋经济向质量效益型转变；要保护海洋生态环境，着力推动海洋开发方式向循环利用型转变；要发展海洋科学技术，着力推动海洋科技向创新引领型转变；要维护国家海洋权益，着力推动海洋维权向统筹兼顾型转变。因此，选项中“开发方式向经济利益主导型转变”说法错误。应为“推动海洋开发方式向循环利用型转变”。\n\n④项正确，习近平主席强调：“建设强大的现代化海军是建设世界一流军队的重要标志，是建设海洋强国的战略支撑，是实现中华民族伟大复兴中国梦的重要组成部分。”综上，①②④正确。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/B类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[2,3]},"idx":2,"pid":"p071b6c2956","sourceYears":[2025]},{"qid":"sy-b-20251025-004","no":4,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[3]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20251025-004-题目-p02-429-552.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②"},{"k":"B","t":"①③"},{"k":"C","t":"②④"},{"k":"D","t":"③④"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20251025-004-解析-p03-131-695.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"工业和信息化部等五部门组织修订的强制性国家标准《电动自行车安全技术规范》（GB17761-2024），于2025年9月1日实施。下列说法符合该技术规范的是（    ）。\n\n①为保障行车安全，电动自行车必须安装后视镜\n\n②可使用电助力功能的电动自行车应具有脚踏骑行装置\n\n③具有电驱动功能的电动自行车最高设计车速不得超过40km/h\n\n④用于城市物流、商业租赁等经营性活动的电动自行车，应具有北斗模块","options":[{"k":"A","t":"①②"},{"k":"B","t":"①③"},{"k":"C","t":"②④"},{"k":"D","t":"③④"}],"material":"","explanation":"4\n\n本题考查时事政治。\n\n①项错误，根据《电动自行车安全技术规范》6.1.5.1 尺寸限值要求：电动自行车的尺寸限值应符合下列要求。a）整车高度（除后视镜及后视镜连接杆外）小于或等于1100mm；车体宽度（除车把、脚蹬、后视镜及后视镜连接杆外）小于或等于400mm；前后轮中心距小于或等于1250mm；鞍座高度大于或等于635mm。仅具有电助力功能的电动自行车的整车高度、前后轮中心距限值要求不适用。注：为保证行车安全，鼓励电动自行车安装后视镜。\n\n原文是鼓励安装后视镜，但没有规定必须安装。\n\n②项正确，根据《电动自行车安全技术规范》6.1.4.1 脚踏骑行要求：可使用电助力功能的电动自行车应具有脚踏骑行装置，并符合下列要求：a）应具有脚踏动力装置；b）脚踏骑行一周，车辆向前行驶距离应大于或等于2.7m；c）两曲柄外侧面最大距离应小于或等于300mm；d）鞍座前端在水平方向位置不应超过中轴中心线。仅具有电驱动功能的电动自行车，可设置脚踏骑行装置，也可不设置脚踏骑行装置。如设置，则应满足上述a）~d）的要求。\n\n③项错误，根据《电动自行车安全技术规范》6.1.1.1 车速限值要求，a 使用电驱动功能行驶时，最高车速不应超过最高设计车速，且最高设计车速不应超过25km/h；如果车速超过25km/h，电动机不应提供动力输出。注：连续下坡行驶等情况下，车速可能会超过25km/h。\n\n④项正确，根据《电动自行车安全技术规范》6.6.1 北斗模块的安装：用于城市物流、商业租赁等经营性活动的电动自行车，应具有北斗模块，且应安装于电动自行车不易损坏的固定部件中，并具备防拆卸、防篡改功能。采用通用工具、剪线、跳线等方式验证防拆卸、防篡改功能。对于其他类型的电动自行车，应设计有北斗模块，销售时由消费者选择是否保留。\n\n综上所述，正确的是②和④。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/B类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[3]},"idx":3,"pid":"p071b6c2956","sourceYears":[2025]},{"qid":"sy-c-20251025-001","no":1,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-001-题目-p02-106-181.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"水下兵器方队——潜匿大洋，出奇制胜"},{"k":"B","t":"电子对抗方队——自主巡弋，出击深蓝"},{"k":"C","t":"装备保障方队——抢救抢修，分秒必争"},{"k":"D","t":"对空抗击方队——剑指苍穹，御敌长空"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-001-解析-p01-120-469.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"纪念中国人民抗日战争暨世界反法西斯战争胜利80周年阅兵活动备受瞩目，本次阅兵中，下列受阅方队与解说词对应错误的是（    ）。","options":[{"k":"A","t":"水下兵器方队——潜匿大洋，出奇制胜"},{"k":"B","t":"电子对抗方队——自主巡弋，出击深蓝"},{"k":"C","t":"装备保障方队——抢救抢修，分秒必争"},{"k":"D","t":"对空抗击方队——剑指苍穹，御敌长空"}],"material":"","explanation":"1\n\n本题考查时事政治。\n\nA 项正确，水下兵器方队主要装备鱼雷等水下作战武器，其核心特点是依托海洋隐蔽部署、伺机突袭。阅兵当天解说词这样描述：“潜匿大洋，出奇制胜，水下兵器方队亮相阅兵场。”\n\nB 项错误，电子对抗方队的核心职能是通过电磁干扰、电子防御等手段争夺制电磁权，属于“无形战场”的作战力量。阅兵当天解说词这样描述：“电磁利剑，先手制敌，电子对抗方队开过来了。”“自主巡弋，出击深蓝。”对应的是海上无人作战方队。海上无人作战方队包括新型无人潜航器、无人艇、无人布雷系统，具备隐蔽布放封锁、自主探测识别、集群组网攻击等作战能力，是海上作战的奇兵利器。\n\nC 项正确，装备保障方队的主要任务是战场装备抢救、抢修和运输，确保作战装备持续发挥效能。阅兵当天解说词这样描述：“抢救抢修，分秒必争，接下来通过的是装备保障方队。”\n\nD 项正确，对空抗击方队以防空武器系统为主要装备，负责抵御空中来袭目标。阅兵当天解说词这样描述：“剑指苍穹，御敌长空，对空抗击方队接受检阅。”\n\n本题为选非题，故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1]},"idx":0,"pid":"p56f583c407","sourceYears":[2025]},{"qid":"sy-c-20251025-002","no":2,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-002-题目-p02-176-299.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-002-解析-p01-464-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-002-解析-p02-51-247.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"习近平总书记指出，推进中国式现代化必须推动海洋经济高质量发展，走出一条具有中国特色的向海图强之路。关于海洋强国建设，下列说法正确的是（   ）。\n\n①建设海洋强国是实现中华民族伟大复兴的重大战略任务\n\n②要加强海湾经济发展规划研究，有序推进沿海港口群优化整合\n\n③要保护海洋生态环境，着力推动海洋开发方式向经济利益主导型转变\n\n④建设强大的现代化海军是建设世界一流军队的重要标志，是建设海洋强国的战略支撑","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"2\n\n本题考查时事政治。\n\n①项正确，2022 年4 月10 日，习近平总书记在中国海洋大学三亚海洋研究院调研考察时，对建设海洋强国作出重要指示：“建设海洋强国是实现中华民族伟大复兴的重大战略任务。”\n\n②项正确，2025 年7 月1 日，习近平主持召开中央财经委员会第六次会议强调：“推动海洋经济高质量发展，要加强顶层设计，加大政策支持力度······要加强海湾经济发展规划研究，有序推进沿海港口群优化整合。”\n\n③项错误，习近平总书记在主持中共中央政治局就建设海洋强国研究进行集体学习时（2013年7 月30 日）强调了建设海洋强国的四个基本要求，即“四个转变”。具体内容为：要提高海洋资源开发能力，着力推动海洋经济向质量效益型转变；要保护海洋生态环境，着力推动海洋开发方式向循环利用型转变；要发展海洋科学技术，着力推动海洋科技向创新引领型转变；要维护国家海洋权益，着力推动海洋维权向统筹兼顾型转变。因此，选项中“开发方式向经济利益主导型转变”说法错误。应为“推动海洋开发方式向循环利用型转变”。\n\n④项正确，习近平主席强调：“建设强大的现代化海军是建设世界一流军队的重要标志，是建设海洋强国的战略支撑，是实现中华民族伟大复兴中国梦的重要组成部分。”综上，①②④正确。\n\n故正确答案为B"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1,2]},"idx":1,"pid":"p56f583c407","sourceYears":[2025]},{"qid":"sy-c-20251025-003","no":3,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-003-题目-p02-295-370.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"大力发展超高层建筑，完善抗震设计标准"},{"k":"B","t":"严格落实安全生产责任制，坚持党政同责"},{"k":"C","t":"多部门、跨城市协同，强化公共卫生联防联控"},{"k":"D","t":"构建总量充足、布局合理的应急避难场所体系"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-003-解析-p02-243-663.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"城市是现代化建设的重要载体、人民幸福生活的重要空间。2025年8月，《中共中央国务院关于推动城市高质量发展的意见》公布，其中明确提出要增强城市安全韧性，下列做法与这一任务要求不符的是（    ）。","options":[{"k":"A","t":"大力发展超高层建筑，完善抗震设计标准"},{"k":"B","t":"严格落实安全生产责任制，坚持党政同责"},{"k":"C","t":"多部门、跨城市协同，强化公共卫生联防联控"},{"k":"D","t":"构建总量充足、布局合理的应急避难场所体系"}],"material":"","explanation":"3\n\n本题考查时事政治。\n\n2025 年8 月15 日，《中共中央国务院关于推动城市高质量发展的意见》公布，其中明确提出要增强城市安全韧性。具体包括以下四项措施：加强房屋和市政基础设施安全管理；强化重点行业领域安全生产管理；提高城市公共卫生防控救治水平；增强城市综合防灾减灾救灾能力。\n\nA 项错误，超高层建筑存在固有安全风险，与城市安全韧性要求存在冲突。文件原文强调，“加强房屋和市政基础设施安全管理。······严格限制超高层建筑，增强高空消防能力。”\n\nB 项正确，文件强调，“强化重点行业领域安全生产管理。严格落实安全生产责任制，坚持党政同责，坚持管行业必须管安全、管业务必须管安全、管生产经营必须管安全，督促生产经营单位落实安全生产主体责任。”\n\nC 项正确，文件强调，“提高城市公共卫生防控救治水平。······推进多部门、跨城市协同，强化公共卫生应急管理和联防联控。健全精神卫生服务体系。”\n\nD 项正确，文件强调，“增强城市综合防灾减灾救灾能力。······统筹利用地上地下空间，加强“平急两用”公共基础设施建设，构建总量充足、布局合理的应急避难场所体系。科学制定巨灾应急预案。”\n\n本题为选非题，故正确答案为A"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[2]},"idx":2,"pid":"p56f583c407","sourceYears":[2025]},{"qid":"sy-c-20251025-004","no":4,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[2,3]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-004-题目-p02-365-424.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"0～6岁儿童"},{"k":"B","t":"高血压患者"},{"k":"C","t":"65岁以上老年人"},{"k":"D","t":"急性脑卒中患者"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-004-解析-p02-658-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-004-解析-p03-51-199.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2025年8月，国务院常务会议审议通过《医疗卫生强基工程实施方案》方案指出，强化重点人群系统连续服务。下列不属于上述重点人群的是（    ）。","options":[{"k":"A","t":"0～6岁儿童"},{"k":"B","t":"高血压患者"},{"k":"C","t":"65岁以上老年人"},{"k":"D","t":"急性脑卒中患者"}],"material":"","explanation":"4\n\n本题考查时事政治。\n\n2025 年8 月，国务院常务会议审议通过《医疗卫生强基工程实施方案》方案指出，强化孕产妇、0—6 岁儿童、65 岁以上老年人以及高血压、2 型糖尿病、慢阻肺病患者等重点人群系统连续服务，加强基层多病共防、多病共管和医防融合，到2030 年高血压、2 型糖尿病患者基层规范管理服务率达到70%以上。\n\n因此“急性脑卒中患者”不属于重点人群。\n\n本题为选非题，故正确答案为D"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[2,3]},"idx":3,"pid":"p56f583c407","sourceYears":[2025]},{"qid":"sy-c-20251025-005","no":5,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[3]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20251025-005-题目-p02-419-542.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②"},{"k":"B","t":"①③"},{"k":"C","t":"②④"},{"k":"D","t":"③④"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20251025-005-解析-p03-195-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20251025-005-解析-p04-51-88.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"工业和信息化部等五部门组织修订的强制性国家标准《电动自行车安全技术规范》（GB17761-2024），于2025年9月1日实施。下列说法符合该技术规范的是（   ）。\n\n①为保障行车安全，电动自行车必须安装后视镜\n\n②可使用电助力功能的电动自行车应具有脚踏骑行装置\n\n③具有电驱动功能的电动自行车最高设计车速不得超过40km/h\n\n④用于城市物流、商业租赁等经营性活动的电动自行车，应具有北斗模块","options":[{"k":"A","t":"①②"},{"k":"B","t":"①③"},{"k":"C","t":"②④"},{"k":"D","t":"③④"}],"material":"","explanation":"5\n\n本题考查时事政治。\n\n①项错误，根据《电动自行车安全技术规范》6.1.5.1 尺寸限值要求：电动自行车的尺寸限值应符合下列要求。a）整车高度（除后视镜及后视镜连接杆外）小于或等于1100mm；车体宽度（除车把、脚蹬、后视镜及后视镜连接杆外）小于或等于400mm；前后轮中心距小于或等于1250mm；鞍座高度大于或等于635mm。仅具有电助力功能的电动自行车的整车高度、前后轮中心距限值要求不适用。注：为保证行车安全，鼓励电动自行车安装后视镜。\n\n原文是鼓励安装后视镜，但没有规定必须安装。\n\n②项正确，根据《电动自行车安全技术规范》6.1.4.1 脚踏骑行要求：可使用电助力功能的电动自行车应具有脚踏骑行装置，并符合下列要求：a）应具有脚踏动力装置；b）脚踏骑行一周，车辆向前行驶距离应大于或等于2.7m；c）两曲柄外侧面最大距离应小于或等于300mm；d）鞍座前端在水平方向位置不应超过中轴中心线。仅具有电驱动功能的电动自行车，可设置脚踏骑行装置，也可不设置脚踏骑行装置。如设置，则应满足上述a）~d）的要求。\n\n③项错误，根据《电动自行车安全技术规范》6.1.1.1 车速限值要求，a 使用电驱动功能行驶时，最高车速不应超过最高设计车速，且最高设计车速不应超过25km/h；如果车速超过25km/h，电动机不应提供动力输出。注：连续下坡行驶等情况下，车速可能会超过25km/h。\n\n④项正确，根据《电动自行车安全技术规范》6.6.1 北斗模块的安装：用于城市物流、商业租赁等经营性活动的电动自行车，应具有北斗模块，且应安装于电动自行车不易损坏的固定部件中，并具备防拆卸、防篡改功能。采用通用工具、剪线、跳线等方式验证防拆卸、防篡改功能。对于其他类型的电动自行车，应设计有北斗模块，销售时由消费者选择是否保留。\n\n综上所述，正确的是②和④。\n\n故正确答案为C"},"from":{"file":"07-事业编职测/C类/2025/2025-10-25/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[3]},"idx":4,"pid":"p56f583c407","sourceYears":[2025]},{"qid":"sy-a-20240330-001","no":1,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20240330-001-题目-p01-106-213.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"落实落细就业优先政策"},{"k":"B","t":"保障好困难群众的基本生活"},{"k":"C","t":"切实提升产业链供应链韧性和安全水平"},{"k":"D","t":"补齐医疗卫生特别是城乡基层医疗卫生公共服务的短板"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20240330-001-解析-p01-138-420.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"中国共产党第二十届中央委员会第二次全体会议公报中强调，要着力加强保障和改善民生各项工作，下列各项工作举措中，不属于保障和改善民生工作的是（  ）。","options":[{"k":"A","t":"落实落细就业优先政策"},{"k":"B","t":"保障好困难群众的基本生活"},{"k":"C","t":"切实提升产业链供应链韧性和安全水平"},{"k":"D","t":"补齐医疗卫生特别是城乡基层医疗卫生公共服务的短板"}],"material":"","explanation":"1、本题考查时政真题。\n\nA、B、D 项正确，中国共产党第二十届中央委员会第二次全体会议公报指出，要着力加强保障和改善民生各项工作，落实落细就业优先政策，保障好困难群众的基本生活，扎牢社会保障网，补齐医疗卫生特别是城乡基层医疗卫生公共服务的短板，完善生育支持政策体系。全面推进乡村振兴，巩固拓展脱贫攻坚成果，防止发生规模性返贫。\n\nC 项错误，中国共产党第二十届中央委员会第二次全体会议公报指出，要努力扩大内需，切实提升产业链供应链韧性和安全水平，进一步优化市场化法治化国际化营商环境，有效防范化解重大经济金融风险，守住不发生系统性风险的底线。\n\n本题为选非题，故正确答案为C。"},"from":{"file":"07-事业编职测/A类/2024/2024-03-30/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"p0fb2b6fc7d","sourceYears":[2024]},{"qid":"sy-a-20240330-002","no":2,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20240330-002-题目-p01-208-347.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①--上海②--浙江③--广西④--黑龙江"},{"k":"B","t":"①--广西②--浙江③--黑龙江④--上海"},{"k":"C","t":"①--浙江②--黑龙江③--上海④--广西"},{"k":"D","t":"①--黑龙江②--上海③--浙江④--广西"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20240330-002-解析-p01-415-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20240330-002-解析-p02-51-375.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023年，习近平总书记赴地方进行了深入考察并提出要求，以下为习近平总书记在考察时强调的部分内容：\n\n①在维护国家国防安全、粮食安全、生态安全、能源安全、产业安全中积极履职尽责\n\n②聚焦建设国际经济中心、金融中心、贸易中心、航运中心、科技创新中心的重要使命\n\n③坚持一张蓝图绘到底，持续推动“八八战略”走深走实，始终干在实处，走在前列，勇立潮头\n\n④发挥自身优势，以铸牢中华民族共同体意识为主线，解放思想、创新求变，向海图强、开放发展下列关于考察时强调的内容及与之相对应的地区，匹配正确的是（  ）。","options":[{"k":"A","t":"①--上海②--浙江③--广西④--黑龙江"},{"k":"B","t":"①--广西②--浙江③--黑龙江④--上海"},{"k":"C","t":"①--浙江②--黑龙江③--上海④--广西"},{"k":"D","t":"①--黑龙江②--上海③--浙江④--广西"}],"material":"","explanation":"2、本题考查时政真题。\n\n①：2023 年9 月6 日至8 日，中共中央总书记、国家主席、中央军委主席习近平在黑龙江考察。习近平总书记强调，东北应在维护国家国防安全、粮食安全、生态安全、能源安全、产业安全中积极履职尽责，这是赋予东北的重要战略使命。\n\n②：2023 年11 月28 日至12 月2 日，中共中央总书记、国家主席、中央军委主席习近平在上海考察。习近平总书记强调，上海要完整、准确、全面贯彻新发展理念，围绕推动高质量发展、构建新发展格局，聚焦建设国际经济中心、金融中心、贸易中心、航运中心、科技创新中心的重要使命，以科技创新为引领，以改革开放为动力，以国家重大战略为牵引，以城市治理现代化为保障，勇于开拓、积极作为，加快建成具有世界影响力的社会主义现代化国际大都市，在推进中国式现代化中充分发挥龙头带动和示范引领作用。\n\n③：2023 年9 月20 日至21 日，中共中央总书记、国家主席、中央军委主席习近平在浙江考察。习近平总书记强调，要完整准确全面贯彻新发展理念，围绕构建新发展格局、推动高质量发展，聚焦建设共同富裕示范区、打造新时代全面展示中国特色社会主义制度优越性的重要窗口，坚持一张蓝图绘到底，持续推动“八八战略”走深走实，始终干在实处、走在前列、勇立潮头，奋力谱写中国式现代化浙江新篇章。\n\n④：2023 年12 月14 日至15 日，中共中央总书记、国家主席、中央军委主席习近平在广西考察。习近平总书记强调，广西要完整、准确、全面贯彻新发展理念，牢牢把握高质量发展这个首要任务和构建新发展格局这个战略任务，发挥自身优势，以铸牢中华民族共同体意识为主线，解放思想、创新求变，向海图强、开放发展，努力在推动边疆民族地区高质量发展上展现更大作为，在建设新时代中国特色社会主义壮美广西上不断取得新进展，奋力谱写中国式现代化广西篇章。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/A类/2024/2024-03-30/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[1,2]},"idx":1,"pid":"p0fb2b6fc7d","sourceYears":[2024]},{"qid":"sy-a-20240330-003","no":3,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20240330-003-题目-p01-343-482.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20240330-003-解析-p02-370-701.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"习近平总书记指出，党的十八大以来，我们积极探索新时代金融发展规律，不断加深对中国特色社会主义金融本质的认识，不断推进金融实践创新、理论创新、制度创新，积累了宝贵经验，逐步走出一条中国特色金融发展之路。下列体现中国特色金融发展之路基本立场、观点、方法的是（ ）。\n\n①坚持以人民为中心的价值取向\n\n②坚持以充分发挥金融的指挥棒作用为目标\n\n③坚持把防控风险作为金融工作的永恒主题\n\n④坚持在市场化法治化轨道上推进金融创新发展","options":[{"k":"A","t":"①②③"},{"k":"B","t":"①②④"},{"k":"C","t":"①③④"},{"k":"D","t":"②③④"}],"material":"","explanation":"3、本题考查时政真题。\n\n2024 年1 月16 日上午，省部级主要领导干部推动金融高质量发展专题研讨班在中央党校（国家行政学院）开班。习近平指出，党的十八大以来，我们积极探索新时代金融发展规律，不断加深对中国特色社会主义金融本质的认识，不断推进金融实践创新、理论创新、制度创新，积累了宝贵经验，逐步走出一条中国特色金融发展之路，这就是：坚持党中央对金融工作的集中统一领导，坚持以人民为中心的价值取向，坚持把金融服务实体经济作为根本宗旨，坚持把防控风险作为金融工作的永恒主题，坚持在市场化法治化轨道上推进金融创新发展，坚持深化金融供给侧结构性改革，坚持统筹金融开放和安全，坚持稳中求进工作总基调。\n\n这几条明确了新时代新征程金融工作怎么看、怎么干，是体现中国特色金融发展之路基本立场、观点、方法的有机整体。\n\n故正确答案为C。"},"from":{"file":"07-事业编职测/A类/2024/2024-03-30/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[2]},"idx":2,"pid":"p0fb2b6fc7d","sourceYears":[2024]},{"qid":"sy-a-20240330-013","no":13,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[9,10]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20240330-013-题目-p02-493-680.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①③④⑤⑦"},{"k":"B","t":"①④⑤⑦⑧"},{"k":"C","t":"②③④⑥⑧"},{"k":"D","t":"②③⑤⑥⑦"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20240330-013-解析-p09-284-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-a-20240330-013-解析-p10-51-570.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"目前我国已有多项非物质文化遗产项目入选联合国教科文组织非遗名录名册，总数位居世界第一。下列入选上述名录名册的有（ ）。\n\n①昆曲\n\n②桂林山水\n\n③中国书法\n\n④南京云锦织造技艺\n\n⑤中医针灸\n\n⑥颐和园\n\n⑦太极拳\n\n⑧粤菜","options":[{"k":"A","t":"①③④⑤⑦"},{"k":"B","t":"①④⑤⑦⑧"},{"k":"C","t":"②③④⑥⑧"},{"k":"D","t":"②③⑤⑥⑦"}],"material":"","explanation":"13、本题考查时政真题。\n\n截至2023 年12 月，中国列入联合国教科文组织非物质文化遗产名录（名册）项目共计43 项，总数位居世界第一。在中国，非物质文化遗产是指各族人民世代相传，并视为其文化遗产组成部分的各种传统文化表现形式，以及与传统文化表现形式相关的实物和场所。\n\n①项正确，昆曲于2008 年入选，昆曲是现存的中国最古老的剧种之一，起源于明代（公元14—17 世纪）。昆曲的唱腔具有很强的艺术性，对中国近代的所有戏剧剧种，如川剧、京剧都有着巨大的影响。\n\n②项错误，桂林山水属于喀斯特地貌。桂林山水一向以山青、水秀、洞奇、石美而享有“山水甲天下”的美誉，桂林山水包括山、水、喀斯特岩洞、石刻等等。2014年，以“桂林山水”为代表的中国南方喀斯特地貌被联合国教科文组织列入《世界自然遗产名录》。\n\n③项正确，中国书法于2009 年入选，中国书法是以笔、墨、纸等为主要工具材料，通过汉字书写，在完成信息交流实用功能的同时，以特有的造型符号和笔墨韵律，融入人们对自然、社会、生命的思考，从而表现出中国人特有的思维方式、人格精神与性情志趣的一种艺术实践。\n\n④项正确，2006 年5 月20 日，南京云锦织造技艺经国务院批准列入第一批国家级非物质文化遗产名录。2009 年9 月30 日，中国南京云锦织造技艺经联合国教科文组织保护非物质文化遗产政府间委员会批准列入人类非物质文化遗产代表作名录。\n\n⑤项正确，2010 年，中医针灸列入联合国教科文组织“人类非物质文化遗产代表作名录”。中医针灸是传统中医的一种医疗手段，除在中国得到广泛应用之外，在东南亚、欧洲和美洲地区也有实践。\n\n⑥项错误，1988 年，联合国教科文组织决定将颐和园列入“世界人类文化遗产名录”。此前于本年7 月，颐和园被中央文明办、建设部、国家旅游局确定为首批10 个全国文明风景旅游区之一。\n\n⑦项正确，2020 年12 月，联合国教科文组织保护非物质文化遗产政府间委员会第15 届常会将“太极拳”项目列入联合国教科文组织人类非物质文化遗产代表作名录。\n\n⑧项错误，在清代形成鲁、川、粤、苏四大菜，后来，闽、浙、湘、徽等地方菜也逐渐出名，于是形成了中国的“八大菜系”，即鲁菜、川菜、粤菜、苏菜、闽菜、浙菜、湘菜、徽菜。未被列入联合国教科文组织非物质文化遗产名录。\n\n①③④⑤⑦正确。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/A类/2024/2024-03-30/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[9,10]},"idx":12,"pid":"p0fb2b6fc7d","sourceYears":[2024]},{"qid":"sy-b-20240330-001","no":1,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20240330-001-题目-p01-106-213.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"落实落细就业优先政策"},{"k":"B","t":"保障好困难群众的基本生活"},{"k":"C","t":"切实提升产业链供应链韧性和安全水平"},{"k":"D","t":"补齐医疗卫生特别是城乡基层医疗卫生公共服务的短板"}],"answer":"C","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20240330-001-解析-p01-138-420.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"中国共产党第二十届中央委员会第二次全体会议公报中强调，要着力加强保障和改善民生各项工作，下列各项工作举措中，不属于保障和改善民生工作的是（  ）。","options":[{"k":"A","t":"落实落细就业优先政策"},{"k":"B","t":"保障好困难群众的基本生活"},{"k":"C","t":"切实提升产业链供应链韧性和安全水平"},{"k":"D","t":"补齐医疗卫生特别是城乡基层医疗卫生公共服务的短板"}],"material":"","explanation":"1、本题考查时政真题。\n\nA、B、D 项正确，中国共产党第二十届中央委员会第二次全体会议公报指出，要着力加强保障和改善民生各项工作，落实落细就业优先政策，保障好困难群众的基本生活，扎牢社会保障网，补齐医疗卫生特别是城乡基层医疗卫生公共服务的短板，完善生育支持政策体系。全面推进乡村振兴，巩固拓展脱贫攻坚成果，防止发生规模性返贫。\n\nC 项错误，中国共产党第二十届中央委员会第二次全体会议公报指出，要努力扩大内需，切实提升产业链供应链韧性和安全水平，进一步优化市场化法治化国际化营商环境，有效防范化解重大经济金融风险，守住不发生系统性风险的底线。\n\n本题为选非题，故正确答案为C。"},"from":{"file":"07-事业编职测/B类/2024/2024-03-30/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[1]},"idx":0,"pid":"pb8bf388b20","sourceYears":[2024]},{"qid":"sy-b-20240330-003","no":3,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20240330-003-题目-p01-327-466.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①③"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"③④"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20240330-003-解析-p02-257-555.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"党的二十大报告把教育科技人才单独成章进行布局，吹响了加快建设教育强国的号角。习近平总书记在二十届中央政治局第五次集体学习时指出，要扎实推动教育强国建设。对于中国特色社会主义强国，下列说法正确的是（ ）。\n\n①以支撑引领中国式现代化为核心功能\n\n②以服务中华民族伟大复兴为基本任务\n\n③以坚持党对教育事业的全面领导为根本目标\n\n④以教育理念、体系、制度、内容方法、治理现代化为基本路径","options":[{"k":"A","t":"①③"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"③④"}],"material":"","explanation":"3、本题考查时政真题。\n\n①④正确，2023 年5 月29 日下午，习近平总书记主持二十届中央政治局第五次集体学习并发表重要讲话。习近平强调，我们要建设的教育强国，是中国特色社会主义教育强国，必须以坚持党对教育事业的全面领导为根本保证，以立德树人为根本任务，以为党育人、为国育才为根本目标，以服务中华民族伟大复兴为重要使命，以教育理念、体系、制度、内容、方法、治理现代化为基本路径，以支撑引领中国式现代化为核心功能，最终是办好人民满意的教育。\n\n②错误，“服务中华民族伟大复兴”是重要使命，而非基本任务。\n\n③错误，“坚持党对教育事业的全面领导”是根本保证，而非根本目标。\n\n故正确答案为B。"},"from":{"file":"07-事业编职测/B类/2024/2024-03-30/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[2]},"idx":2,"pid":"pb8bf388b20","sourceYears":[2024]},{"qid":"sy-b-20240330-004","no":4,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[2,3]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20240330-004-题目-p01-461-600.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①--上海②--浙江③--广西④--黑龙江"},{"k":"B","t":"①--广西②--浙江③--黑龙江④--上海"},{"k":"C","t":"①--浙江②--黑龙江③--上海④--广西"},{"k":"D","t":"①--黑龙江②--上海③--浙江④--广西"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20240330-004-解析-p02-550-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-b-20240330-004-解析-p03-51-526.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023年，习近平总书记赴地方进行了深入考察并提出要求，以下为习近平总书记在考察时强调的部分内容：\n\n①在维护国家国防安全、粮食安全、生态安全、能源安全、产业安全中积极履职尽责\n\n②聚焦建设国际经济中心、金融中心、贸易中心、航运中心、科技创新中心的重要使命\n\n③坚持一张蓝图绘到底，持续推动“八八战略”走深走实，始终干在实处，走在前列，勇立潮头\n\n④发挥自身优势，以铸牢中华民族共同体意识为主线，解放思想、创新求变，向海图强、开放发展下列关于考察时强调的内容及与之相对应的地区，匹配正确的是（ ）。","options":[{"k":"A","t":"①--上海②--浙江③--广西④--黑龙江"},{"k":"B","t":"①--广西②--浙江③--黑龙江④--上海"},{"k":"C","t":"①--浙江②--黑龙江③--上海④--广西"},{"k":"D","t":"①--黑龙江②--上海③--浙江④--广西"}],"material":"","explanation":"4、本题考查时政真题。\n\n①：2023 年9 月6 日至8 日，中共中央总书记、国家主席、中央军委主席习近平在黑龙江考察。习近平总书记强调，东北应在维护国家国防安全、粮食安全、生态安全、能源安全、产业安全中积极履职尽责，这是赋予东北的重要战略使命。\n\n②：2023 年11 月28 日至12 月2 日，中共中央总书记、国家主席、中央军委主席习近平在上海考察。习近平总书记强调，上海要完整、准确、全面贯彻新发展理念，围绕推动高质量发展、构建新发展格局，聚焦建设国际经济中心、金融中心、贸易中心、航运中心、科技创新中心的重要使命，以科技创新为引领，以改革开放为动力，以国家重大战略为牵引，以城市治理现代化为保障，勇于开拓、积极作为，加快建成具有世界影响力的社会主义现代化国际大都市，在推进中国式现代化中充分发挥龙头带动和示范引领作用。\n\n③：2023 年9 月20 日至21 日，中共中央总书记、国家主席、中央军委主席习近平在浙江考察。习近平总书记强调，要完整准确全面贯彻新发展理念，围绕构建新发展格局、推动高质量发展，聚焦建设共同富裕示范区、打造新时代全面展示中国特色社会主义制度优越性的重要窗口，坚持一张蓝图绘到底，持续推动“八八战略”走深走实，始终干在实处、走在前列、勇立潮头，奋力谱写中国式现代化浙江新篇章。\n\n④：2023 年12 月14 日至15 日，中共中央总书记、国家主席、中央军委主席习近平在广西考察。习近平总书记强调，广西要完整、准确、全面贯彻新发展理念，牢牢把握高质量发展这个首要任务和构建新发展格局这个战略任务，发挥自身优势，以铸牢中华民族共同体意识为主线，解放思想、创新求变，向海图强、开放发展，努力在推动边疆民族地区高质量发展上展现更大作为，在建设新时代中国特色社会主义壮美广西上不断取得新进展，奋力谱写中国式现代化广西篇章。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/B类/2024/2024-03-30/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[2,3]},"idx":3,"pid":"pb8bf388b20","sourceYears":[2024]},{"qid":"sy-c-20240330-002","no":2,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[1],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20240330-002-题目-p01-224-363.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"①--上海②--浙江③--广西④--黑龙江"},{"k":"B","t":"①--广西②--浙江③--黑龙江④--上海"},{"k":"C","t":"①--浙江②--黑龙江③--上海④--广西"},{"k":"D","t":"①--黑龙江②--上海③--浙江④--广西"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20240330-002-解析-p01-473-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20240330-002-解析-p02-51-253.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"2023年，习近平总书记赴地方进行了深入考察并提出要求，以下为习近平总书记在考察时强调的部分内容：\n\n①在维护国家国防安全、粮食安全、生态安全、能源安全、产业安全中积极履职尽责\n\n②聚焦建设国际经济中心、金融中心、贸易中心、航运中心、科技创新中心的重要使命\n\n③坚持一张蓝图绘到底，持续推动“八八战略”走深走实，始终干在实处，走在前列，勇立潮头\n\n④发挥自身优势，以铸牢中华民族共同体意识为主线，解放思想、创新求变，向海图强、开放发展下列关于考察时强调的内容及与之相对应的地区，匹配正确的是（ ）。","options":[{"k":"A","t":"①--上海②--浙江③--广西④--黑龙江"},{"k":"B","t":"①--广西②--浙江③--黑龙江④--上海"},{"k":"C","t":"①--浙江②--黑龙江③--上海④--广西"},{"k":"D","t":"①--黑龙江②--上海③--浙江④--广西"}],"material":"","explanation":"2、本题考查时政真题。\n\n①：2023 年9 月6 日至8 日，中共中央总书记、国家主席、中央军委主席习近平在黑龙江考察。习近平总书记强调，东北应在维护国家国防安全、粮食安全、生态安全、能源安全、产业安全中积极履职尽责，这是赋予东北的重要战略使命。\n\n②：2023 年11 月28 日至12 月2 日，中共中央总书记、国家主席、中央军委主席习近平在上海考察。习近平总书记强调，上海要完整、准确、全面贯彻新发展理念，围绕推动高质量发展、构建新发展格局，聚焦建设国际经济中心、金融中心、贸易中心、航运中心、科技创新中心的重要使命，以科技创新为引领，以改革开放为动力，以国家重大战略为牵引，以城市治理现代化为保障，勇于开拓、积极作为，加快建成具有世界影响力的社会主义现代化国际大都市，在推进中国式现代化中充分发挥龙头带动和示范引领作用。\n\n③：2023 年9 月20 日至21 日，中共中央总书记、国家主席、中央军委主席习近平在浙江考察。习近平总书记强调，要完整准确全面贯彻新发展理念，围绕构建新发展格局、推动高质量发展，聚焦建设共同富裕示范区、打造新时代全面展示中国特色社会主义制度优越性的重要窗口，坚持一张蓝图绘到底，持续推动“八八战略”走深走实，始终干在实处、走在前列、勇立潮头，奋力谱写中国式现代化浙江新篇章。\n\n④：2023 年12 月14 日至15 日，中共中央总书记、国家主席、中央军委主席习近平在广西考察。习近平总书记强调，广西要完整、准确、全面贯彻新发展理念，牢牢把握高质量发展这个首要任务和构建新发展格局这个战略任务，发挥自身优势，以铸牢中华民族共同体意识为主线，解放思想、创新求变，向海图强、开放发展，努力在推动边疆民族地区高质量发展上展现更大作为，在建设新时代中国特色社会主义壮美广西上不断取得新进展，奋力谱写中国式现代化广西篇章。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2024/2024-03-30/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[1],"answerPages":[1,2]},"idx":1,"pid":"p3f16ff5043","sourceYears":[2024]},{"qid":"sy-a-20241102-001","no":1,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20241102-001-题目-p02-155-313.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"高校、科研院所、公立医院开展公开招聘须由相应主管部门统一组织"},{"k":"B","t":"资格审查部门（单位）可以委托考试服务机构进行相关资格审查工作"},{"k":"C","t":"各地区可以自行制定面向特定人员的事业单位专项招聘，考试加分等政策"},{"k":"D","t":"招聘公告按程序备案后须在事业单位人事综合管理部门招聘平台公开发布"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20241102-001-解析-p01-107-381.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题）2024年8月，中共中央组织部、人力资源社会保障部印发《关于进一步做好事业单位公开招聘工作的通知》（以下简称《通知》），对改进和规范事业单位公开招聘工作提出要求。根据《通知》内容，下列说法正确的是：","options":[{"k":"A","t":"高校、科研院所、公立医院开展公开招聘须由相应主管部门统一组织"},{"k":"B","t":"资格审查部门（单位）可以委托考试服务机构进行相关资格审查工作"},{"k":"C","t":"各地区可以自行制定面向特定人员的事业单位专项招聘，考试加分等政策"},{"k":"D","t":"招聘公告按程序备案后须在事业单位人事综合管理部门招聘平台公开发布"}],"material":"","explanation":"本题考查时政真题。\n\n1\n\nA项错误，《关于进一步做好事业单位公开招聘工作的通知》指出，高校、科研院所、公立医院以及其他规模较大的面向社会提供公益服务的事业单位，可以按照规定程序和要求自主组织开展公开招聘。\n\nB项错误，《关于进一步做好事业单位公开招聘工作的通知》指出，资格审查应当严格规范。要按照招聘公告明确的资格条件进行资格审查，符合公告所列条件的应聘人员原则上都应当允许进入下一个招聘环节，不得进行“简历筛选”。资格审查工作不得委托考试服务机构等第三方进行。\n\nC项错误，《关于进一步做好事业单位公开招聘工作的通知》指出，各地区各部门各单位不得自行制定面向特定人员的专项招聘、加分等事业单位公开招聘倾斜政策，不得随意扩大国家规定的倾斜政策范围。省级事业单位人事综合管理部门要对本地区现有倾斜政策进行规范，确有必要继续实施的，需报中央事业单位人事综合管理部门同意。\n\nD项正确，《关于进一步做好事业单位公开招聘工作的通知》指出，规范招聘信息发布工作。招聘公告、补充公告等信息按程序备案后须在事业单位人事综合管理部门招聘平台公开发布，可同时在事业单位或者主管部门网站显著位置发布，不得仅通过内部网站、社交媒体或者张贴布告等方式在特定人员范围内发布。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/A类/2024/2024-11-02/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1]},"idx":0,"pid":"p278ae760c2","sourceYears":[2024]},{"qid":"sy-a-20241102-002","no":2,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20241102-002-题目-p02-309-403.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"坚持系统观念"},{"k":"B","t":"坚持高质量发展"},{"k":"C","t":"坚持以人民为中心"},{"k":"D","t":"坚持全面依法治国"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20241102-002-解析-p01-377-495.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题）2024年7月18日，中国共产党第二十届中央委员会第三次全体会议通过《中共中央关于进一步全面深化改革 推进中国式现代化的决定》，指出进一步全面深化改革要贯彻六大原则，其中不包括：","options":[{"k":"A","t":"坚持系统观念"},{"k":"B","t":"坚持高质量发展"},{"k":"C","t":"坚持以人民为中心"},{"k":"D","t":"坚持全面依法治国"}],"material":"","explanation":"本题考查时政真题。\n\n2《中共中央关于进一步全面深化改革 推进中国式现代化的决定》指出，进一步全面深化改革的原则。\n\n总结和运用改革开放以来特别是新时代全面深化改革的宝贵经验，贯彻以下原则：坚持党的全面领导；坚持以人民为中心；坚持守正创新；坚持以制度建设为主线；坚持全面依法治国；坚持系统观念。\n\n本题为选非题，故正确答案为B。"},"from":{"file":"07-事业编职测/A类/2024/2024-11-02/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1]},"idx":1,"pid":"p278ae760c2","sourceYears":[2024]},{"qid":"sy-a-20241102-003","no":3,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-a-20241102-003-题目-p02-399-557.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"深化科技评价体系改革，加强科技伦理治理，严肃整治学术不端行为"},{"k":"B","t":"优化资源配置，建立与区域经济发展水平相协调的义务教育供给机制"},{"k":"C","t":"强化人才激励机制，人才评价更加注重以创新理念、研究成果为导向"},{"k":"D","t":"鼓励高校按照先付费后使用的方式将科研成果许可给中小微企业使用"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-a-20241102-003-解析-p01-491-720.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题） 2024年7月18日，中国共产党第二十届中央委员会第三次全体会议通过了《中共中央关于进一步全面深化改革 推进中国式现代化的决定》，其中对推进教育科技人才体制机制一体改革作出了重要部署。对此，下列说法正确的是：","options":[{"k":"A","t":"深化科技评价体系改革，加强科技伦理治理，严肃整治学术不端行为"},{"k":"B","t":"优化资源配置，建立与区域经济发展水平相协调的义务教育供给机制"},{"k":"C","t":"强化人才激励机制，人才评价更加注重以创新理念、研究成果为导向"},{"k":"D","t":"鼓励高校按照先付费后使用的方式将科研成果许可给中小微企业使用"}],"material":"","explanation":"3\n\n本题考查时事政治。\n\nA项正确，《决定》指出，改进科技计划管理，强化基础研究领域、交叉前沿领域、重点领域前瞻性、引领性布局。加强有组织的基础研究，提高科技支出用于基础研究比重。深化科技评价体系改革，加强科技伦理治理，严肃整治学术不端行为。\n\nB项错误，《决定》指出，优化区域教育资源配置，建立同人口变化相协调的基本公共教育服务供给机制。完善义务教育优质均衡推进机制，探索逐步扩大免费教育范围。\n\nC项错误，《决定》指出，强化人才激励机制，坚持向用人主体授权、为人才松绑。建立以创新能力、质量、实效、贡献为导向的人才评价体系。打通高校、科研院所和企业人才交流通道。\n\nD项错误，《决定》指出，强化企业科技创新主体地位，建立培育壮大科技领军企业机制，加强企业主导的产学研深度融合，建立企业研发准备金制度，支持企业主动牵头或参与国家科技攻关任务等。鼓励和引导高校、科研院所按照先使用后付费方式把科技成果许可给中小微企业使用。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/A类/2024/2024-11-02/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1]},"idx":2,"pid":"p278ae760c2","sourceYears":[2024]},{"qid":"sy-b-20241102-001","no":1,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20241102-001-题目-p02-155-271.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"成绩合格分数线设定不得低于满分的60%"},{"k":"B","t":"不得借“人才引进”名义违规“绕道进人”"},{"k":"C","t":"资格审查应当贯穿事业单位公开招聘全过程"},{"k":"D","t":"提高命题工作质量，坚持“干什么、考什么”"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20241102-001-解析-p01-107-306.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题）2024年8月，中共中央组织部、人力资源社会保障部印发《关于进一步做好事业单位公开招聘工作的通知》（以下简称《通知》），对改进和规范事业单位公开招聘工作提出要求。根据《通知》内容，下列说法错误的是：","options":[{"k":"A","t":"成绩合格分数线设定不得低于满分的60%"},{"k":"B","t":"不得借“人才引进”名义违规“绕道进人”"},{"k":"C","t":"资格审查应当贯穿事业单位公开招聘全过程"},{"k":"D","t":"提高命题工作质量，坚持“干什么、考什么”"}],"material":"","explanation":"本题考查时事政治。\n\n1\n\nA项错误，根据《通知》内容，根据考试难易程度、岗位要求等，合理设定成绩合格分数线，未达到成绩合格分数线的人员不得进入招聘下一个环节，避免超低分聘用问题。\n\nB项正确，根据《通知》内容，严格按照《事业单位公开招聘人员暂行规定》等相关规定实施招聘。不得借“人才引进”等名义违反事业单位公开招聘规定搞“绕道进人”。\n\nC项正确，根据《通知》内容，资格审查应当严格规范。资格审查应当贯穿公开招聘全过程，任何环节发现应聘人员不符合资格条件的，均应取消应聘或者聘用资格。\n\nD项正确，根据《通知》内容，切实提高命题工作质量。坚持“干什么、考什么”，严格执行命题工作规则和要求，坚决防止出现试题抄袭拼凑、重复使用等问题。\n\n本题为选非题，故正确答案为A。"},"from":{"file":"07-事业编职测/B类/2024/2024-11-02/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1]},"idx":0,"pid":"pb6aa22c843","sourceYears":[2024]},{"qid":"sy-b-20241102-002","no":2,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20241102-002-题目-p02-267-361.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"加强师范生科技史教育"},{"k":"B","t":"落实教职员工从业禁止制度"},{"k":"C","t":"实施数字化赋能教师发展行动"},{"k":"D","t":"支持高校教师开展跨学科研究"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20241102-002-解析-p01-302-516.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题）2024年8月，《中共中央 国务院关于弘扬教育家精神加强新时代高素质专业化教师队伍建设的意见》发布，其中指出要提升教师专业素养。下列举措不属于此项内容的是：","options":[{"k":"A","t":"加强师范生科技史教育"},{"k":"B","t":"落实教职员工从业禁止制度"},{"k":"C","t":"实施数字化赋能教师发展行动"},{"k":"D","t":"支持高校教师开展跨学科研究"}],"material":"","explanation":"本题考查时事政治。\n\n2\n\nA项正确，《意见》指出，提升教师专业素养。（七）健全中国特色教师教育体系。师范院校普遍建立数学、科技、工程类教育中心，加强师范生科技史教育，提高科普传播能力。\n\nB项错误，《意见》指出，涵养高尚师德师风。（六）坚持师德违规“零容忍”。落实教职员工准入查询和从业禁止制度。该项不属于“提升教师专业素养”的措施。\n\nC项正确，《意见》指出，提升教师专业素养。（九）提升教师教书育人能力。实施数字化赋能教师发展行动，推动教师积极应对新技术变革，着眼未来培养人才。\n\nD项正确，《意见》指出，提升教师专业素养。（八）提高教师学科能力和学科素养。适应基础学科、新兴学科、交叉学科发展趋势，支持高校教师开展跨学科学习与研究，加强学科领军人才队伍建设，发挥引领带动作用。\n\n本题为选非题，故正确答案为B。"},"from":{"file":"07-事业编职测/B类/2024/2024-11-02/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1]},"idx":1,"pid":"pb6aa22c843","sourceYears":[2024]},{"qid":"sy-b-20241102-003","no":3,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20241102-003-题目-p02-357-515.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"深化科技评价体系改革，加强科技伦理治理，严肃整治学术不端行为"},{"k":"B","t":"优化资源配置，建立与区域经济发展水平相协调的义务教育供给机制"},{"k":"C","t":"强化人才激励机制，人才评价更加注重以创新理念、研究成果为导向"},{"k":"D","t":"鼓励高校按照先付费后使用的方式将科研成果许可给中小微企业使用"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20241102-003-解析-p01-512-741.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题） 2024年7月18日，中国共产党第二十届中央委员会第三次全体会议通过了《中共中央关于进一步全面深化改革 推进中国式现代化的决定》，其中对推进教育科技人才体制机制一体改革作出了重要部署。对此，下列说法正确的是：","options":[{"k":"A","t":"深化科技评价体系改革，加强科技伦理治理，严肃整治学术不端行为"},{"k":"B","t":"优化资源配置，建立与区域经济发展水平相协调的义务教育供给机制"},{"k":"C","t":"强化人才激励机制，人才评价更加注重以创新理念、研究成果为导向"},{"k":"D","t":"鼓励高校按照先付费后使用的方式将科研成果许可给中小微企业使用"}],"material":"","explanation":"本题考查时事政治。\n\n3\n\nA项正确，《决定》指出，改进科技计划管理，强化基础研究领域、交叉前沿领域、重点领域前瞻性、引领性布局。加强有组织的基础研究，提高科技支出用于基础研究比重，······。深化科技评价体系改革，加强科技伦理治理，严肃整治学术不端行为。\n\nB项错误，《决定》指出，优化区域教育资源配置，建立同人口变化相协调的基本公共教育服务供给机制。完善义务教育优质均衡推进机制，探索逐步扩大免费教育范围。\n\nC项错误，《决定》指出，强化人才激励机制，坚持向用人主体授权、为人才松绑。建立以创新能力、质量、实效、贡献为导向的人才评价体系。打通高校、科研院所和企业人才交流通道。\n\nD项错误，《决定》指出，强化企业科技创新主体地位，建立培育壮大科技领军企业机制，加强企业主导的产学研深度融合，建立企业研发准备金制度，支持企业主动牵头或参与国家科技攻关任务。\n\n······。鼓励和引导高校、科研院所按照先使用后付费方式把科技成果许可给中小微企业使用。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/B类/2024/2024-11-02/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1]},"idx":2,"pid":"pb6aa22c843","sourceYears":[2024]},{"qid":"sy-b-20241102-004","no":4,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-b-20241102-004-题目-p02-511-627.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"推进领导干部能上能下常态化"},{"k":"B","t":"向行业龙头企业全面派驻纪检监察组"},{"k":"C","t":"探索加强新就业群体党的建设有效途径"},{"k":"D","t":"持续精简规范会议文件和各类创建示范活动"}],"answer":"B","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-b-20241102-004-解析-p01-737-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-b-20241102-004-解析-p02-51-246.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题）2024年7月18日，中国共产党第二十届中央委员会第三次全体会议通过《中共中央关于进一步全面深化改革 推进中国式现代化的决定》。该《决定》提出“提高党对进一步全面深化改革、推进中国式现代化的领导水平”。下列举措不符合该决定中相关内容精神的是：","options":[{"k":"A","t":"推进领导干部能上能下常态化"},{"k":"B","t":"向行业龙头企业全面派驻纪检监察组"},{"k":"C","t":"探索加强新就业群体党的建设有效途径"},{"k":"D","t":"持续精简规范会议文件和各类创建示范活动"}],"material":"","explanation":"本题考查时事政治。\n\n4\n\nA项正确，《决定》指出，深化党的建设制度改革。以调动全党抓改革、促发展的积极性、主动性、创造性为着力点，完善党的建设制度机制。······推进领导干部能上能下常态化，加大调整不适宜担任现职干部力度。\n\nB项错误，《决定》指出，完善党和国家监督体系。强化全面从严治党主体责任和监督责任。······优化监督检查和审查调查机构职能，完善垂直管理单位纪检监察体制，推进向中管企业全面派驻纪检监察组。应是向“中管企业”全面派驻纪检监察组。\n\nC项正确，《决定》指出，深化党的建设制度改革。······增强党组织政治功能和组织功能。探索加强新经济组织、新社会组织、新就业群体党的建设有效途径。完善党员教育管理、作用发挥机制。\n\nD项正确，《决定》指出，深入推进党风廉政建设和反腐败斗争。······持续精简规范会议文件和各类创建示范、评比达标、节庆展会论坛活动，严格控制面向基层的督查、检查、考核总量，提高调研质量，下大气力解决过频过繁问题。\n\n本题为选非题，故正确答案为B。"},"from":{"file":"07-事业编职测/B类/2024/2024-11-02/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1,2]},"idx":3,"pid":"pb6aa22c843","sourceYears":[2024]},{"qid":"sy-c-20241102-001","no":1,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20241102-001-题目-p02-155-313.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"深化科技评价体系改革，加强科技伦理治理，严肃整治学术不端行为"},{"k":"B","t":"优化资源配置，建立与区域经济发展水平相协调的义务教育供给机制"},{"k":"C","t":"强化人才激励机制，人才评价更加注重以创新理念、研究成果为导向"},{"k":"D","t":"鼓励高校按照先付费后使用的方式将科研成果许可给中小微企业使用"}],"answer":"A","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20241102-001-解析-p01-106-336.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题） 2024年7月18日，中国共产党第二十届中央委员会第三次全体会议通过了《中共中央关于进一步全面深化改革 推进中国式现代化的决定》，其中对推进教育科技人才体制机制一体改革作出了重要部署。对此，下列说法正确的是：","options":[{"k":"A","t":"深化科技评价体系改革，加强科技伦理治理，严肃整治学术不端行为"},{"k":"B","t":"优化资源配置，建立与区域经济发展水平相协调的义务教育供给机制"},{"k":"C","t":"强化人才激励机制，人才评价更加注重以创新理念、研究成果为导向"},{"k":"D","t":"鼓励高校按照先付费后使用的方式将科研成果许可给中小微企业使用"}],"material":"","explanation":"1\n\n本题考查时事政治。\n\nA项正确，《决定》指出，改进科技计划管理，强化基础研究领域、交叉前沿领域、重点领域前瞻性、引领性布局。加强有组织的基础研究，提高科技支出用于基础研究比重，······。深化科技评价体系改革，加强科技伦理治理，严肃整治学术不端行为。\n\nB项错误，《决定》指出，优化区域教育资源配置，建立同人口变化相协调的基本公共教育服务供给机制。完善义务教育优质均衡推进机制，探索逐步扩大免费教育范围。\n\nC项错误，《决定》指出，强化人才激励机制，坚持向用人主体授权、为人才松绑。建立以创新能力、质量、实效、贡献为导向的人才评价体系。打通高校、科研院所和企业人才交流通道。\n\nD项错误，《决定》指出，强化企业科技创新主体地位，建立培育壮大科技领军企业机制，加强企业主导的产学研深度融合，建立企业研发准备金制度，支持企业主动牵头或参与国家科技攻关任务。\n\n······。鼓励和引导高校、科研院所按照先使用后付费方式把科技成果许可给中小微企业使用。\n\n故正确答案为A。"},"from":{"file":"07-事业编职测/C类/2024/2024-11-02/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1]},"idx":0,"pid":"p4dd91af038","sourceYears":[2024]},{"qid":"sy-c-20241102-003","no":3,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[1,2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20241102-003-题目-p02-441-535.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"开展节能灶具下乡活动"},{"k":"B","t":"加强绿色产品和服务认证管理"},{"k":"C","t":"推广“光盘行动”、抵制过度包装"},{"k":"D","t":"实施农业减排固碳行动，优化种养结构"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20241102-003-解析-p01-661-812.jpg\" class=\"fig source-crop\" alt=\"试题原图\"><img src=\"assets/img/institution/sy-c-20241102-003-解析-p02-51-186.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题）2024年，《中共中央 国务院关于加快经济社会发展全面绿色转型的意见》发布，其中提出“推动消费模式绿色转型”，下列举措不属于此项内容的是：","options":[{"k":"A","t":"开展节能灶具下乡活动"},{"k":"B","t":"加强绿色产品和服务认证管理"},{"k":"C","t":"推广“光盘行动”、抵制过度包装"},{"k":"D","t":"实施农业减排固碳行动，优化种养结构"}],"material":"","explanation":"3\n\n本题考查时政真题。\n\nA项正确，在《中共中央国务院关于加快经济社会发展全面绿色转型的意见》的“八、推动消费模式绿色转型”中，（二十）积极扩大绿色消费指出：“开展新能源汽车和绿色智能家电、节水器具、节能灶具、绿色建材下乡活动，加强配套设施建设和售后服务保障。鼓励用户扩大绿色能源消费。”\n\nB项正确，在《中共中央国务院关于加快经济社会发展全面绿色转型的意见》的“八、推动消费模式绿色转型”中，（十九）加大绿色产品供给指出：“加强绿色产品和服务认证管理，完善认证机构监管机制，培育具有国际影响力的绿色认证机构。”\n\nC项正确，在《中共中央国务院关于加快经济社会发展全面绿色转型的意见》的“八、推动消费模式绿色转型”中，（十八）推广绿色生活方式指出：“开展绿色低碳全民行动，引导公众节约用水用电、反对铺张浪费、推广“光盘行动”、抵制过度包装、减少一次性用品使用，引导公众优先选择公共交通、步行、自行车等绿色出行方式，广泛开展爱国卫生运动，推动解决噪声、油烟、恶臭等群众身边的环境问题，形成崇尚生态文明的社会氛围。”\n\nD项错误，在《中共中央国务院关于加快经济社会发展全面绿色转型的意见》的“六、推进城乡建设发展绿色转型”中，（十四）推动农业农村绿色发展指出：“实施农业农村减排固碳行动，优化种养结构，推广优良作物畜禽品种和绿色高效栽培养殖技术，推进化肥、农药等农业投入品减量增效。”\n\n本题为选非题，故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2024/2024-11-02/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[1,2]},"idx":2,"pid":"p4dd91af038","sourceYears":[2024]},{"qid":"sy-c-20241102-004","no":4,"type":"常识时政","module":"常识判断","classification":{"version":"shiye-v1.20261011","group":"时事政治","tag":"时事政治","auxiliary":[],"methods":[],"forms":[],"confidence":"原分类","needsReview":false,"rule":"source.original","evidence":"保留题库原分类；本次讲义未覆盖细分","curriculum":null,"basis":"保留原题分类","frameworkVersion":"fenbi-v2.20261011","sourcePages":{"paper":[2],"answer":[2]}},"stem":"<div class=\"source-question\"><img src=\"assets/img/institution/sy-c-20241102-004-题目-p02-531-625.jpg\" class=\"fig source-crop\" alt=\"试题原图\"></div>","options":[{"k":"A","t":"亚冬会一般每五年举办一次"},{"k":"B","t":"上届亚冬会是由蒙古国承办的"},{"k":"C","t":"第九届亚冬会的吉祥物是丹顶鹤造型"},{"k":"D","t":"哈尔滨将于2025年第二次承办亚冬会"}],"answer":"D","multi":false,"answerStatus":"reference","explanation":"<img src=\"assets/img/institution/sy-c-20241102-004-解析-p02-182-366.jpg\" class=\"fig source-crop\" alt=\"试题原图\">","original":true,"sourceText":{"stem":"（单选题）第九届亚洲冬季运动会（简称亚冬会）将在黑龙江省哈尔滨市举行。下列关于亚冬会的说法正确的是：","options":[{"k":"A","t":"亚冬会一般每五年举办一次"},{"k":"B","t":"上届亚冬会是由蒙古国承办的"},{"k":"C","t":"第九届亚冬会的吉祥物是丹顶鹤造型"},{"k":"D","t":"哈尔滨将于2025年第二次承办亚冬会"}],"material":"","explanation":"4\n\n本题考查时政真题。\n\nA项错误，亚冬会是每四年举办一次，与奥运会、冬奥会等国际大型体育赛事的举办周期相一致。\n\nB项错误，根据历史记录，上届（第八届）亚冬会是在日本札幌举行的，而非蒙古国。\n\nC项错误，‌2025年第九届亚洲冬季运动会（亚冬会）的吉祥物是“滨滨”和“妮妮”，它们的原型是东北虎，而不是丹顶鹤。\n\nD项正确，哈尔滨亚冬会是继北京冬奥会后我国举办的又一重大综合性国际冰雪盛会。中国此前举办过两届亚冬会，分别是1996年在哈尔滨和2007年在长春。2025年是哈尔滨第二次承办亚冬会，在哈尔滨国际会展体育中心将于2月7日举行开幕式，2月14日举行闭幕式。\n\n故正确答案为D。"},"from":{"file":"07-事业编职测/C类/2024/2024-11-02/常识判断.md","module":"常识判断","sourceModule":"常识判断","sourceType":"时事政治","questionPages":[2],"answerPages":[2]},"idx":3,"pid":"p4dd91af038","sourceYears":[2024]}]};
